from fastapi import FastAPI, Request, Depends, HTTPException
from fastapi.responses import JSONResponse

app = FastAPI()

class LicenseRevokedError(Exception):
    def __init__(self, license_id: str):
        self.license_id = license_id

@app.exception_handler(LicenseRevokedError)
async def license_revoked_handler(request: Request, exc: LicenseRevokedError):
    return JSONResponse(
        status_code=410,
        content={
            "error": "LicenseAlreadyRevoked",
            "license_id": exc.license_id,
            "detail": "This software license has already been permanently revoked"
        }
    )

@app.post("/drm/licenses/{license_id}/revoke")
async def revoke_license(
    license_id: str,
    drm_service: DRMService = Depends(get_drm_service),
    current_user: User = Depends(get_current_user)
):
    license_entry = await drm_service.get_license(license_id)
    if not license_entry:
        raise HTTPException(status_code=404, detail="License not found")
    if license_entry.owner_id != current_user.id and not current_user.is_licensing_admin:
        raise HTTPException(status_code=403, detail="Forbidden: unauthorized to manage this license")

    if license_entry.is_revoked:
        raise LicenseRevokedError(license_id)

    await drm_service.perform_revocation(license_id, current_user.id)
    return {"status": "revoked", "license_id": license_id}
